window.FP_BIRD={"items": [{"t": "stay", "s": "", "q": "How do room prices work, and can children stay?", "a": " Our rates are  per room for two adults , with continental breakfast included, plus taxes and fees. Each room above shows its price per night.   Children 0–12 stay at no extra charge.  Most rooms take  2 adults and 1 child . Rooms with  two double beds  (Hotel Suite Double, Ocean View Double and Pool Walk-out Double) take  2 adults and 2 children . A third adult (13 and over) is  $25 per night , taxes included. ", "k": "rate rates price cost night kids", "l": [["See the rooms", "#stay"]], "h": "<p>Our rates are <strong>per room for two adults</strong>, with continental breakfast included, plus taxes and fees. Each room above shows its price per night.</p><p><strong>Children 0–12 stay at no extra charge.</strong> Most rooms take <strong>2 adults and 1 child</strong>. Rooms with <strong>two double beds</strong> (Hotel Suite Double, Ocean View Double and Pool Walk-out Double) take <strong>2 adults and 2 children</strong>. A third adult (13 and over) is <strong>$25 per night</strong>, taxes included.</p>", "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in.", "Room prices are <strong>per room, for two</strong>, plus 10% government tax, 15% service charge and the US$1 per night Jamaica hospitality tax."]}, {"t": "stay", "s": "", "q": "Is FootePrints all-inclusive?", "a": " We’re a boutique hotel rather than an all-inclusive resort, and  continental breakfast is included  with every room.  If you’d like everything covered, add our optional  All-Inclusive Plan :  $165 per adult  and  $100 per child aged 4–12 , per night, for the whole stay. ", "k": "all inclusive plan meals included all inclusive plan meals drinks included food package", "l": [["Rooms and the plan", "#stay"]], "h": "<p>We’re a boutique hotel rather than an all-inclusive resort, and <strong>continental breakfast is included</strong> with every room.</p><p>If you’d like everything covered, add our optional <strong>All-Inclusive Plan</strong>: <strong>$165 per adult</strong> and <strong>$100 per child aged 4–12</strong>, per night, for the whole stay.</p>", "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in.", "Room prices are <strong>per room, for two</strong>, plus 10% government tax, 15% service charge and the US$1 per night Jamaica hospitality tax.", "The plan follows your room nights, from check-in at 3 PM to check-out at 12 PM. A <strong>late check-out doesn’t extend the plan</strong>, so lunch on your departure day is charged separately."]}, {"t": "stay", "s": "", "q": "What should I know before I arrive?", "a": " Check-in is  from 3 PM  and check-out is  by 12 PM .  Late check-out is  $60 until 3 PM  or  $120 until 6 PM , available when the hotel isn’t fully booked and your room isn’t needed for arriving guests. Add it to your room request, or ask the front desk.  We’re a  cashless property , so please bring a card, and hotel guests have a  $200 card pre-authorisation  at check-in. ", "k": "checkin checkout check-in check-out times late deposit checkin checkout check-in check-out times late deposit arrive arrival", "l": [], "h": "<p>Check-in is <strong>from 3 PM</strong> and check-out is <strong>by 12 PM</strong>.</p><p>Late check-out is <strong>$60 until 3 PM</strong> or <strong>$120 until 6 PM</strong>, available when the hotel isn’t fully booked and your room isn’t needed for arriving guests. Add it to your room request, or ask the front desk.</p><p>We’re a <strong>cashless property</strong>, so please bring a card, and hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in.</p>", "n": []}, {"t": "stay", "s": "", "q": "Why can’t I book some rooms online?", "a": " Our  Oceanfront, Pool Walk-out and Deluxe rooms  are only bookable with us: they aren’t on any booking site. Tap  Request these dates  on the room: you’ll see the full price for your dates before you send it, and our team replies within 24–48 hours. ", "k": "", "l": [], "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in.", "Room prices are <strong>per room, for two</strong>, plus 10% government tax, 15% service charge and the US$1 per night Jamaica hospitality tax."], "h": "<p>Our <strong>Oceanfront, Pool Walk-out and Deluxe rooms</strong> are only bookable with us: they aren’t on any booking site. Tap <strong>Request these dates</strong> on the room: you’ll see the full price for your dates before you send it, and our team replies within 24–48 hours.</p>"}, {"t": "stay", "s": "", "q": "Which rooms have a balcony?", "a": " Each of our  four Oceanfront rooms  has a balcony, and the  Deluxe Hotel Suite  has a large private one. For other rooms we can’t promise a balcony. ", "k": "", "l": [], "n": [], "h": "<p>Each of our <strong>four Oceanfront rooms</strong> has a balcony, and the <strong>Deluxe Hotel Suite</strong> has a large private one. For other rooms we can’t promise a balcony.</p>"}, {"t": "stay", "s": "", "q": "Do you have rooms for guests with limited mobility?", "a": " Yes. Our  two Pool Walk-out rooms  are on the ground floor, with no stairs to your door. Mention it when you book. ", "k": "", "l": [], "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in."], "h": "<p>Yes. Our <strong>two Pool Walk-out rooms</strong> are on the ground floor, with no stairs to your door. Mention it when you book.</p>"}, {"t": "stay", "s": "", "q": "Can you arrange an airport transfer?", "a": " Yes, a private car from  Montego Bay airport , taxes included:  $125 one way  or  $250 round trip , for up to four people. Add it to your room request, or email us for a bigger group or a transfer from Kingston. ", "k": "", "l": [["Email reservations", "mailto:reservations@negrilfooteprints.com"]], "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in.", "Room prices are <strong>per room, for two</strong>, plus 10% government tax, 15% service charge and the US$1 per night Jamaica hospitality tax."], "h": "<p>Yes, a private car from <strong>Montego Bay airport</strong>, taxes included: <strong>$125 one way</strong> or <strong>$250 round trip</strong>, for up to four people. Add it to your room request, or email us for a bigger group or a transfer from Kingston.</p>"}, {"t": "stay", "s": "", "q": "Is there a local rate for Jamaican residents?", "a": "  Yes: 10% off the room rate  for Jamaican residents. Tick  I live in Jamaica  in your room request and the price updates straight away.  Please have a  valid Jamaican ID or proof of residency  ready: our reservations team may ask for it before payment, and the front desk checks it again at check-in. Without it, the standard rate applies. ", "k": "", "l": [["WhatsApp reservations", "https://wa.me/18558223591"]], "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in.", "Room prices are <strong>per room, for two</strong>, plus 10% government tax, 15% service charge and the US$1 per night Jamaica hospitality tax."], "h": "<p><strong>Yes: 10% off the room rate</strong> for Jamaican residents. Tick <strong>I live in Jamaica</strong> in your room request and the price updates straight away.</p><p>Please have a <strong>valid Jamaican ID or proof of residency</strong> ready: our reservations team may ask for it before payment, and the front desk checks it again at check-in. Without it, the standard rate applies.</p>"}, {"t": "stay", "s": "", "q": "Is this the old Foote Prints on the Sands?", "a": " Yes. It is  the same beachfront property  on Seven Mile Beach, fully renovated and renamed  Negril FootePrints Hotel . ", "k": "", "l": [], "n": [], "h": "<p>Yes. It is <strong>the same beachfront property</strong> on Seven Mile Beach, fully renovated and renamed <strong>Negril FootePrints Hotel</strong>.</p>"}, {"t": "stay", "s": "", "q": "What rooms do you have?", "a": " We have  32 rooms , in five kinds:    Hotel Suite  (9 rooms): garden view, king or two double beds. From  $259  per night.   Ocean View Suite  (14 rooms): a one-bedroom suite with a sitting area, views over the pool, gardens and the Caribbean Sea. From  $259 .   Deluxe Suites  (3 rooms): two Deluxe Junior Suites and one Deluxe Hotel Suite, the only room with a bathtub and a large private balcony. From  $349 , by request.   Pool Walk-out Rooms  (2 rooms): ground floor, opening onto the pool, no stairs. From  $349 ,  only bookable with us .   Oceanfront Rooms  (4 rooms): facing the Caribbean Sea, each with a balcony. From  $349 ,  only bookable with us .   Every room has free Wi-Fi, air conditioning, a smart TV, an in-room safe and a minibar. Not sure which to choose?  Compare rooms  on the Stay page shows every room side by side for your dates, taxes included. ", "h": "<p>We have <strong>32 rooms</strong>, in five kinds:</p><ul class=\"bm-ul\"><li><strong>Hotel Suite</strong> (9 rooms): garden view, king or two double beds. From <span class=\"rate\" data-t=\"1\">$279</span> per night.</li><li><strong>Ocean View Suite</strong> (14 rooms): a one-bedroom suite with a sitting area, views over the pool, gardens and the Caribbean Sea. From <span class=\"rate\" data-t=\"1\">$279</span> per night.</li><li><strong>Deluxe Suites</strong> (3 rooms): two Deluxe Junior Suites and one Deluxe Hotel Suite, the only room with a bathtub and a large private balcony. From <span class=\"rate\" data-t=\"3\">$369</span> per night, by request.</li><li><strong>Pool Walk-out Rooms</strong> (2 rooms): ground floor, opening onto the pool, no stairs. From <span class=\"rate\" data-t=\"3\">$369</span> per night, <strong>only bookable with us</strong>.</li><li><strong>Oceanfront Rooms</strong> (4 rooms): facing the Caribbean Sea, each with a balcony. From <span class=\"rate\" data-t=\"3\">$369</span> per night, <strong>only bookable with us</strong>.</li></ul><p>Every room has free Wi-Fi, air conditioning, a smart TV, an in-room safe and a minibar. Not sure which to choose? <strong>Compare rooms</strong> on the Stay page shows every room side by side for your dates, taxes included.</p>", "k": "room types suites suite oceanfront ocean view deluxe pool walkout which room best room", "l": [["See the rooms", "#stay"]], "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in.", "Room prices are <strong>per room, for two</strong>, plus 10% government tax, 15% service charge and the US$1 per night Jamaica hospitality tax."]}, {"t": "stay", "s": "", "q": "What comes with every room?", "a": " With every room:    Continental breakfast  every morning, 7:30 – 11 AM at Blushy’s   Complimentary water , and a  coffee and tea station from 6:30 AM    The beach, the infinity pool, loungers and towels   Free Wi-Fi, air conditioning, a smart TV, an in-room safe and a minibar   Also for hotel guests: a lifeguard on the beach, complimentary kayaks, the FootePrints swing and board games. ", "h": "<p>With every room:</p><ul class=\"bm-ul\"><li><strong>Continental breakfast</strong> every morning, 7:30 – 11 AM at Blushy’s</li><li><strong>Complimentary water</strong>, and a <strong>coffee and tea station from 6:30 AM</strong></li><li><strong>The beach, the infinity pool, loungers and towels</strong></li><li>Free Wi-Fi, air conditioning, a smart TV, an in-room safe and a minibar</li></ul><p>Also for hotel guests: a lifeguard on the beach, complimentary kayaks, the FootePrints swing and board games.</p>", "k": "included amenities breakfast towels pool beach coffee tea water", "l": [["See the rooms", "#stay"]], "n": []}, {"t": "stay", "s": "", "q": "Is breakfast included?", "a": "  Yes.  A  continental breakfast  is included with every room, every morning from  7:30 to 11 AM  at Blushy’s Bar & Grill: Jamaican Blue Mountain coffee, cold brew and teas, seasonal fresh fruit, cereals and whole grains, yogurt, and breakfast pastries with jams and butter.  Hot dishes, like pancakes, eggs or a Jamaican breakfast, are à la carte from the breakfast menu. Children 12 and under have breakfast at no charge. ", "h": "<p><strong>Yes.</strong> A <strong>continental breakfast</strong> is included with every room, every morning from <strong>7:30 to 11 AM</strong> at Blushy’s Bar & Grill: Jamaican Blue Mountain coffee, cold brew and teas, seasonal fresh fruit, cereals and whole grains, yogurt, and breakfast pastries with jams and butter.</p><p>Hot dishes, like pancakes, eggs or a Jamaican breakfast, are à la carte from the breakfast menu. <strong>Children 12 and under</strong> have breakfast at no charge.</p>", "k": "breakfast continental included morning", "l": [["Breakfast menu", "#menu-breakfast"]], "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in.", "Room prices are <strong>per room, for two</strong>, plus 10% government tax, 15% service charge and the US$1 per night Jamaica hospitality tax."]}, {"t": "stay", "s": "", "q": "Do you have Wi-Fi?", "a": "  Yes, free Wi-Fi  in every room. Our meeting room has Wi-Fi too, for teams and retreats. ", "h": "<p><strong>Yes, free Wi-Fi</strong> in every room. Our meeting room has Wi-Fi too, for teams and retreats.</p>", "k": "wifi wi-fi internet wireless", "l": [["See the rooms", "#stay"]], "n": []}, {"t": "stay", "s": "", "q": "What is your cancellation policy?", "a": "   8 or more days before  your stay:  full refund , minus processing fees.   Within 7 days :  50%  of the booking.   Under 24 hours :  no refund , and the same for no-shows.   For a change to your booking, email  reservations@negrilfooteprints.com . ", "h": "<ul class=\"bm-ul\"><li><strong>8 or more days before</strong> your stay: <strong>full refund</strong>, minus processing fees.</li><li><strong>Within 7 days</strong>: <strong>50%</strong> of the booking.</li><li><strong>Under 24 hours</strong>: <strong>no refund</strong>, and the same for no-shows.</li></ul><p>For a change to your booking, email <strong>reservations@negrilfooteprints.com</strong>.</p>", "k": "cancel cancellation refund refunds no-show change dates", "l": [], "n": ["FootePrints is <strong>cashless</strong>: please bring a card. Hotel guests have a <strong>$200 card pre-authorisation</strong> at check-in."]}, {"t": "stay", "s": "", "q": "Can I bring my pet?", "a": " We’re sorry:  pets are not allowed  at FootePrints. ", "h": "<p>We’re sorry: <strong>pets are not allowed</strong> at FootePrints.</p>", "k": "pet pets dog dogs cat animal animals", "l": [], "n": []}, {"t": "daypass", "s": "", "q": "Can I visit for the day or just for a meal?", "a": "  Yes, you don’t need to stay with us.  Walk in for breakfast or lunch at Blushy’s, or dinner at Gatsby’s (we recommend booking dinner).  Or spend the day with a  Day Pass , daily  9 AM – 5 PM :    $30  per adult,  $20  for ages 4–12,  free  for ages 0–3   Included:  a welcome drink, towels, the infinity pool, loungers and umbrellas, your spot on Seven Mile Beach, a lifeguard, an outdoor beach shower, restrooms by the beach, power outlets, complimentary kayaks, the FootePrints swing and board games.   Not included:  food and drinks. Order lunch and drinks from Blushy’s at an extra cost, and they’re brought to your lounger.    How it works:  reserve online, get your QR code by email (nothing is charged online), arrive any time from 9 AM, show your QR code at the front desk and pay by card.  The Day Pass ends at 5 PM, but nobody will rush you: stay for the sunset and dinner at Gatsby’s from 6 PM. ", "k": "day pass price cost ticket day pass price cost ticket visitors non guests walk in", "l": [["Book a Day Pass", "https://www.tickettailor.com/events/negrilfooteprintshotel/2452834"], ["Day Pass details", "#daypass"], ["Dining and menus", "#dining"], ["Day Pass", "#daypass"]], "h": "<p><strong>Yes, you don’t need to stay with us.</strong> Walk in for breakfast or lunch at Blushy’s, or dinner at Gatsby’s (we recommend booking dinner).</p><p>Or spend the day with a <strong>Day Pass</strong>, daily <strong>9 AM – 5 PM</strong>:</p><ul class=\"bm-ul\"><li><strong>$30</strong> per adult, <strong>$20</strong> for ages 4–12, <strong>free</strong> for ages 0–3</li><li><strong>Included:</strong> a welcome drink, towels, the infinity pool, loungers and umbrellas, your spot on Seven Mile Beach, a lifeguard, an outdoor beach shower, restrooms by the beach, power outlets, complimentary kayaks, the FootePrints swing and board games.</li><li><strong>Not included:</strong> food and drinks. Order lunch and drinks from Blushy’s at an extra cost, and they’re brought to your lounger.</li></ul><p><strong>How it works:</strong> reserve online, get your QR code by email (nothing is charged online), arrive any time from 9 AM, show your QR code at the front desk and pay by card.</p><p>The Day Pass ends at 5 PM, but nobody will rush you: stay for the sunset and dinner at Gatsby’s from 6 PM.</p>", "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."]}, {"t": "daypass", "s": "", "q": "Can I book a Day Pass for today?", "a": "  Yes.  Same-day bookings are welcome: reserve online, then come straight over. ", "k": "", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."], "h": "<p><strong>Yes.</strong> Same-day bookings are welcome: reserve online, then come straight over.</p>"}, {"t": "daypass", "s": "", "q": "Can I come without booking?", "a": " You can try, but  we can’t promise you a spot . Day Pass spaces are  limited each day , and the beach closes to day visitors on private event days, on fully booked days and on some holidays.  To be sure of your day,  reserve online before you come . ", "k": "", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless."], "h": "<p>You can try, but <strong>we can’t promise you a spot</strong>. Day Pass spaces are <strong>limited each day</strong>, and the beach closes to day visitors on private event days, on fully booked days and on some holidays.</p><p>To be sure of your day, <strong>reserve online before you come</strong>.</p>"}, {"t": "daypass", "s": "", "q": "What happens if it rains?", "a": " The Day Pass goes ahead  rain or shine , and we don’t refund it for the weather once you’ve arrived.  Please  check the forecast before you come . If it doesn’t look good, you can  move your Day Pass to another date  before your visit. ", "k": "", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."], "h": "<p>The Day Pass goes ahead <strong>rain or shine</strong>, and we don’t refund it for the weather once you’ve arrived.</p><p>Please <strong>check the forecast before you come</strong>. If it doesn’t look good, you can <strong>move your Day Pass to another date</strong> before your visit.</p>"}, {"t": "daypass", "s": "", "q": "Is it cheaper if I arrive late or leave early?", "a": " No.  The price is the same for the day , whether you arrive at 9 AM or 1 PM, and whether you leave at noon or at 5. ", "k": "", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."], "h": "<p>No. <strong>The price is the same for the day</strong>, whether you arrive at 9 AM or 1 PM, and whether you leave at noon or at 5.</p>"}, {"t": "daypass", "s": "", "q": "Can I book for a big group?", "a": " Yes, online like any other booking. You can add  up to 10 people in one booking ; for a bigger group, simply make a second booking for the same date.  Spaces are limited each day, so  book early  for a group. ", "k": "", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless."], "h": "<p>Yes, online like any other booking. You can add <strong>up to 10 people in one booking</strong>; for a bigger group, simply make a second booking for the same date.</p><p>Spaces are limited each day, so <strong>book early</strong> for a group.</p>"}, {"t": "daypass", "s": "", "q": "If we eat at the restaurant, can we stay on the beach?", "a": " A meal at Blushy’s or Gatsby’s  doesn’t include the beach or the pool .  To spend the day on the loungers,  book a Day Pass , then order food and drinks to your chair. ", "k": "", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."], "h": "<p>A meal at Blushy’s or Gatsby’s <strong>doesn’t include the beach or the pool</strong>.</p><p>To spend the day on the loungers, <strong>book a Day Pass</strong>, then order food and drinks to your chair.</p>"}, {"t": "daypass", "s": "", "q": "Can we bring our own food and drinks?", "a": " Food and drinks are served by  Blushy’s Bar & Grill , so please don’t bring your own.   Baby food and snacks for little ones are of course fine.  ", "k": "", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."], "h": "<p>Food and drinks are served by <strong>Blushy’s Bar &amp; Grill</strong>, so please don’t bring your own.</p><p><strong>Baby food and snacks for little ones are of course fine.</strong></p>"}, {"t": "daypass", "s": "", "q": "Do children need a ticket?", "a": " Yes, please add everyone to your booking:  $20 for ages 4–12 , and a  free ticket for ages 0–3 , so we know how many of you are coming. ", "k": "", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."], "h": "<p>Yes, please add everyone to your booking: <strong>$20 for ages 4–12</strong>, and a <strong>free ticket for ages 0–3</strong>, so we know how many of you are coming.</p>"}, {"t": "daypass", "s": "", "q": "What does the Day Pass include?", "a": " Your Day Pass ( $30  per adult,  $20  ages 4–12, free 0–3) includes:   A welcome drink when you arrive  Towels for the day  The infinity pool, loungers and umbrellas  Your spot on Seven Mile Beach, with a lifeguard  An outdoor beach shower and restrooms by the beach  Power outlets to charge your phone  Complimentary kayaks, the FootePrints swing and board games    Food and drinks are not included : order from Blushy’s Bar & Grill to your lounger. Spa treatments are booked separately. ", "h": "<p>Your Day Pass (<strong>$30</strong> per adult, <strong>$20</strong> ages 4–12, free 0–3) includes:</p><ul class=\"bm-ul\"><li>A welcome drink when you arrive</li><li>Towels for the day</li><li>The infinity pool, loungers and umbrellas</li><li>Your spot on Seven Mile Beach, with a lifeguard</li><li>An outdoor beach shower and restrooms by the beach</li><li>Power outlets to charge your phone</li><li>Complimentary kayaks, the FootePrints swing and board games</li></ul><p><strong>Food and drinks are not included</strong>: order from Blushy’s Bar & Grill to your lounger. Spa treatments are booked separately.</p>", "k": "included include what get towels pool loungers kayak shower", "l": [["Book a Day Pass", "https://www.tickettailor.com/events/negrilfooteprintshotel/2452834"], ["Day Pass details", "#daypass"]], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."]}, {"t": "daypass", "s": "", "q": "When is the beach closed to day visitors?", "a": " The beach closes to day visitors  on private event days ,  when the hotel is fully booked , and  on some holidays . Reserve online before you come, so you’re sure of your day. ", "h": "<p>The beach closes to day visitors <strong>on private event days</strong>, <strong>when the hotel is fully booked</strong>, and <strong>on some holidays</strong>. Reserve online before you come, so you’re sure of your day.</p>", "k": "closed close holiday holidays fully booked event private", "l": [], "n": ["You <strong>pay at the hotel on the day, by card</strong>: FootePrints is cashless.", "<strong>Spaces are limited</strong> each day, so reserve ahead."]}, {"t": "daypass", "s": "", "q": "Can I pay in Jamaican dollars?", "a": "  Yes, by card.  Prices are shown in US dollars, and you can pay by card in Jamaican dollars at  J$160 = US$1 . We’re cashless, so cash isn’t accepted. ", "h": "<p><strong>Yes, by card.</strong> Prices are shown in US dollars, and you can pay by card in Jamaican dollars at <strong>J$160 = US$1</strong>. We’re cashless, so cash isn’t accepted.</p>", "k": "jmd j$ jamaican dollars exchange rate currency usd local money", "l": [["Day Pass details", "#daypass"]], "n": ["<strong>Spaces are limited</strong> each day, so reserve ahead."]}, {"t": "dining", "s": "", "q": "Do I need to stay at the hotel to eat here?", "a": "  No.  Breakfast, lunch and dinner are  open to everyone . Walk in for breakfast or lunch at Blushy’s, or book a table for dinner at Gatsby’s. ", "k": "lunch dinner breakfast without staying guests visitors walk walkin public lunch dinner breakfast without staying guests visitors walk walkin public open everyone", "l": [["Breakfast menu", "#menu-breakfast"], ["Lunch menu", "#menu-lunch"], ["Dinner menu", "#menu-dinner"]], "h": "<p><strong>No.</strong> Breakfast, lunch and dinner are <strong>open to everyone</strong>. Walk in for breakfast or lunch at Blushy’s, or book a table for dinner at Gatsby’s.</p>", "n": ["FootePrints is <strong>cashless</strong>, so please pay by card.", "Menu prices are in US dollars, plus <strong>10% government tax and 15% service charge</strong>."]}, {"t": "dining", "s": "", "q": "How does “My order” work?", "a": "Tap <strong>+</strong> next to a dish and it goes into your order; tap <strong>−</strong> to take it out. One order holds one meal (breakfast, lunch or dinner), and drinks can go with any of them. You see the total with tax and service. <strong>Nothing is sent to the kitchen</strong>: show the list to your server and they’ll take it from there.", "k": "", "l": [], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card.", "Menu prices are in US dollars, plus <strong>10% government tax and 15% service charge</strong>."]}, {"t": "dining", "s": "", "q": "Do I need a reservation for dinner?", "a": " Walk-ins are welcome, but  we recommend booking dinner  at Gatsby’s, especially on holidays and special days. ", "k": "", "l": [["Reserve at Gatsby’s", "https://eatapp.co/reserve/gatsby-s-restaurant-at-negril-footeprints-hotel-fa5d27"]], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card.", "Menu prices are in US dollars, plus <strong>10% government tax and 15% service charge</strong>."], "h": "<p>Walk-ins are welcome, but <strong>we recommend booking dinner</strong> at Gatsby’s, especially on holidays and special days.</p>"}, {"t": "dining", "s": "", "q": "Is there a dress code?", "a": " At Gatsby’s in the evening:  resort casual . No swimwear, cover-ups or bare feet, please. ", "k": "", "l": [], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card."], "h": "<p>At Gatsby’s in the evening: <strong>resort casual</strong>. No swimwear, cover-ups or bare feet, please.</p>"}, {"t": "dining", "s": "", "q": "Do you have a children’s menu?", "a": " Children are very welcome.  A children’s menu is coming soon , and  high chairs  are available. Until then, our team is happy to help you choose. ", "k": "", "l": [], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card.", "Menu prices are in US dollars, plus <strong>10% government tax and 15% service charge</strong>."], "h": "<p>Children are very welcome. <strong>A children’s menu is coming soon</strong>, and <strong>high chairs</strong> are available. Until then, our team is happy to help you choose.</p>"}, {"t": "dining", "s": "", "q": "Is there a happy hour?", "a": " Yes,  every day from 4 to 6 PM at Blushy’s Bar & Grill : 2-for-1 on selected cocktails and martinis, Red Stripe and Blushy’s Special. ", "k": "", "l": [["See the drinks menu", "https://menus.negrilfooteprints.com/?from=links#drinks"]], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card."], "h": "<p>Yes, <strong>every day from 4 to 6 PM at Blushy’s Bar &amp; Grill</strong>: 2-for-1 on selected cocktails and martinis, Red Stripe and Blushy’s Special.</p>"}, {"t": "dining", "s": "", "q": "How many people can you seat together?", "a": " Up to  10 guests at one table . Online booking on Eat App is for up to 5 guests. For <strong>6 or more</strong>, send a group table request on the Dining page: a <strong>US$100 non-refundable deposit</strong> holds the table. For a bigger group, contact us and we’ll plan it with you. ", "k": "", "l": [], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card."], "h": "<p>Up to <strong>10 guests at one table</strong>. For a bigger group, contact us and we’ll plan it with you.</p>"}, {"t": "dining", "s": "", "q": "What if I have a food allergy?", "a": " Please mention it  when you book on Eat App , and tell your server when you order. ", "k": "", "l": [], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card.", "Menu prices are in US dollars, plus <strong>10% government tax and 15% service charge</strong>."], "h": "<p>Please mention it <strong>when you book on Eat App</strong>, and tell your server when you order.</p>"}, {"t": "dining", "s": "", "q": "Do you have vegetarian, vegan and gluten-free dishes?", "a": " Yes. Dinner has a  vegetarian section , and dishes are marked  V (vegan)  and  G (gluten-free)  on every menu. ", "k": "vegan vegetarian gluten free food options plant based meat", "l": [], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card.", "Menu prices are in US dollars, plus <strong>10% government tax and 15% service charge</strong>."], "h": "<p>Yes. Dinner has a <strong>vegetarian section</strong>, and dishes are marked <strong>V (vegan)</strong> and <strong>G (gluten-free)</strong> on every menu.</p>"}, {"t": "dining", "s": "", "q": "Are tax and service included in the prices?", "a": " Menu prices are in US dollars and are  subject to 10% government tax and 15% service charge . ", "k": "", "l": [], "n": ["FootePrints is <strong>cashless</strong>, so please pay by card."], "h": "<p>Menu prices are in US dollars and are <strong>subject to 10% government tax and 15% service charge</strong>.</p>"}, {"t": "dining", "s": "", "q": "How do I pay?", "a": " By  card , at the hotel. FootePrints is a  cashless  property. Prices are in US dollars,  plus 10% government tax and 15% service charge : the request form shows your total before you send it. ", "k": "", "l": [], "n": [], "h": "<p>By <strong>card</strong>, at the hotel. FootePrints is a <strong>cashless</strong> property. Prices are in US dollars, <strong>plus 10% government tax and 15% service charge</strong>: the request form shows your total before you send it.</p>"}, {"t": "dining", "s": "", "q": "Can you seat a group of 6 or more?", "a": "Yes. Online booking on Eat App is for <strong>up to 5 guests</strong>. For <strong>6 or more</strong>, send a group table request on the Dining page and we’ll set up your table and reply to confirm. A <strong>US$100 non-refundable deposit</strong> holds a table for 6 or more.", "k": "group party table six large big", "l": [["Dining", "#dining"]], "n": []}, {"t": "dining", "s": "", "q": "Should I tip my server?", "a": "<strong>Tipping is never expected.</strong> A 15% service charge is already on your bill.\n\nIf you enjoyed your meal and the service, you’re always welcome to leave a little extra for the team. They’ll be very grateful.", "k": "tip tipping gratuity", "l": [], "n": []}, {"t": "spa", "s": "", "q": "What treatments do you have?", "a": " Audrey’s Spa is open  daily, 9 AM – 5 PM , for hotel guests, Day Pass guests and visitors.    Massages:  Balancing (60 min  $130 ), Deep Tissue (60 min  $150 ), Hot Stone (75 min  $160 ), Couples (60 min  $250 ), Reflexology (60 min  $100 ), Pregnancy (60 min  $110 ), Express Back (30 min  $90 ).   Facials:  from  $45  (Revitalizing Mini Facial, 30 min) to  $110  (Signature Facial + Back Massage).   Body treatments and scrubs:  from  $70  (Coffee, Sugar or Salt Scrub) to  $150  (Coconut Cocoon, 90 min).   Combinations:  Refresh & Renew (60 min  $90 ), Body Scrub & Massage (75 min  $140 ).   Add to any treatment:  scalp massage  $20 , foot scrub  $25 , foot massage  $30 .   Longer Balancing and Deep Tissue massages (90 and 120 minutes) are on the spa page. ", "h": "<p>Audrey’s Spa is open <strong>daily, 9 AM – 5 PM</strong>, for hotel guests, Day Pass guests and visitors.</p><ul class=\"bm-ul\"><li><strong>Massages:</strong> Balancing (60 min <strong>$130</strong>), Deep Tissue (60 min <strong>$150</strong>), Hot Stone (75 min <strong>$160</strong>), Couples (60 min <strong>$250</strong>), Reflexology (60 min <strong>$100</strong>), Pregnancy (60 min <strong>$110</strong>), Express Back (30 min <strong>$90</strong>).</li><li><strong>Facials:</strong> from <strong>$45</strong> (Revitalizing Mini Facial, 30 min) to <strong>$110</strong> (Signature Facial + Back Massage).</li><li><strong>Body treatments and scrubs:</strong> from <strong>$70</strong> (Coffee, Sugar or Salt Scrub) to <strong>$150</strong> (Coconut Cocoon, 90 min).</li><li><strong>Combinations:</strong> Refresh & Renew (60 min <strong>$90</strong>), Body Scrub & Massage (75 min <strong>$140</strong>).</li><li><strong>Add to any treatment:</strong> scalp massage <strong>$20</strong>, foot scrub <strong>$25</strong>, foot massage <strong>$30</strong>.</li></ul><p>Longer Balancing and Deep Tissue massages (90 and 120 minutes) are on the spa page.</p>", "k": "treatments menu prices massage facial scrub how much list", "l": [["See all treatments", "#spa"]], "n": ["You pay at the hotel, <strong>by card</strong>: FootePrints is cashless. Prices are plus 10% government tax and 15% service charge.", "Treatments are <strong>not included</strong> in the Day Pass or the All-Inclusive Plan."]}, {"t": "spa", "s": "", "q": "Do I need to stay at the hotel?", "a": "  No.  Audrey’s Spa is open to everyone: hotel guests, Day Pass guests and visitors. ", "k": "", "l": [], "n": [], "h": "<p><strong>No.</strong> Audrey’s Spa is open to everyone: hotel guests, Day Pass guests and visitors.</p>"}, {"t": "spa", "s": "", "q": "Can I just walk in?", "a": "  Walk-ins are welcome , but  booking ahead is best , so we can keep a time for you.  Send a request with the  Book a treatment  button and our front desk will confirm your time. ", "k": "", "l": [], "n": ["You pay at the hotel, <strong>by card</strong>: FootePrints is cashless. Prices are plus 10% government tax and 15% service charge.", "Treatments are <strong>not included</strong> in the Day Pass or the All-Inclusive Plan."], "h": "<p><strong>Walk-ins are welcome</strong>, but <strong>booking ahead is best</strong>, so we can keep a time for you.</p><p>Send a request with the <strong>Book a treatment</strong> button and our front desk will confirm your time.</p>"}, {"t": "spa", "s": "", "q": "Does the request confirm my booking?", "a": "  Not yet.  The form sends your wishes to our front desk; it doesn’t show live availability.  We  reply to confirm your time , or suggest the closest one that’s free. ", "k": "", "l": [], "n": ["You pay at the hotel, <strong>by card</strong>: FootePrints is cashless. Prices are plus 10% government tax and 15% service charge."], "h": "<p><strong>Not yet.</strong> The form sends your wishes to our front desk; it doesn’t show live availability.</p><p>We <strong>reply to confirm your time</strong>, or suggest the closest one that’s free.</p>"}, {"t": "spa", "s": "", "q": "Do you have a couples massage?", "a": " Yes. Our  Couples Massage  is  60 minutes, $250 , side by side in the same room.  You can also ask for  any treatment for two people : choose  For 2 people  in the request form. When two of our therapists are free at your time, we’ll do it side by side. ", "k": "", "l": [["Book a treatment", "#spa"]], "h": "<p>Yes. Our <strong>Couples Massage</strong> is <strong>60 minutes, $250</strong>, side by side in the same room.</p><p>You can also ask for <strong>any treatment for two people</strong>: choose <strong>For 2 people</strong> in the request form. When two of our therapists are free at your time, we’ll do it side by side.</p>", "n": ["You pay at the hotel, <strong>by card</strong>: FootePrints is cashless. Prices are plus 10% government tax and 15% service charge.", "Treatments are <strong>not included</strong> in the Day Pass or the All-Inclusive Plan."]}, {"t": "spa", "s": "", "q": "Can I have a massage while pregnant?", "a": " Yes, we offer a  Pregnancy Massage ,  60 minutes, $110 . Please mention it in your request. ", "k": "", "l": [], "n": ["You pay at the hotel, <strong>by card</strong>: FootePrints is cashless. Prices are plus 10% government tax and 15% service charge.", "Treatments are <strong>not included</strong> in the Day Pass or the All-Inclusive Plan."], "h": "<p>Yes, we offer a <strong>Pregnancy Massage</strong>, <strong>60 minutes, $110</strong>. Please mention it in your request.</p>"}, {"t": "spa", "s": "", "q": "Is the spa included in the Day Pass or the All-Inclusive Plan?", "a": "  No.  Spa treatments are booked and paid separately. ", "k": "spa included daypass day pass plan allinclusive massage", "l": [], "n": ["Treatments are <strong>not included</strong> in the Day Pass or the All-Inclusive Plan."], "h": "<p><strong>No.</strong> Spa treatments are booked and paid separately.</p>"}, {"t": "spa", "s": "", "q": "How do I pay?", "a": " By  card , at the hotel. FootePrints is a  cashless  property. Prices are in US dollars,  plus 10% government tax and 15% service charge : the request form shows your total before you send it. ", "k": "", "l": [], "n": ["Treatments are <strong>not included</strong> in the Day Pass or the All-Inclusive Plan."], "h": "<p>By <strong>card</strong>, at the hotel. FootePrints is a <strong>cashless</strong> property. Prices are in US dollars, <strong>plus 10% government tax and 15% service charge</strong>: the request form shows your total before you send it.</p>"}, {"t": "events", "s": "", "q": "Can we celebrate or get married with you?", "a": "We’d love that. Birthdays, anniversaries, baby showers and private dinners are all welcome.\n\nFor weddings, we host everything from an intimate vow renewal on the beach to a celebration for <strong>about 150 guests</strong>, with <strong>all 32 rooms</strong> for your party. Wedding packages start at <strong>US$1,999</strong>.", "k": "", "l": [["Weddings and celebrations", "#events"]], "n": []}, {"t": "events", "s": "Weddings", "q": "How much does a wedding cost?", "a": " Our wedding packages, plus 10% GCT:    Intimate Escape , up to 10 guests: from  US$1,999 . Bouquet and boutonniere, beach venue for up to 2 hours, officiant and coordinator, a one-tier cake and sparkling wine, a candlelight dinner for two.   White Lux , up to 25 guests: from  US$4,700 . All-white roses, a floral arch, Chiavari chairs, cocktail tables, officiant and coordinator, sparkling wine, cake and hors d’oeuvres.   FootePrints Signature Experience , up to 50 guests: from  US$8,999 . A rose bouquet, Louis chairs and floral pedestals, a reception tablescape, a beachfront or Gatsby’s venue for up to 4 hours, officiant and coordinator, cake and a sparkling wine toast, breakfast in bed and a room upgrade (based on availability).   Packages are for the wedding itself;  rooms are booked separately . Every package can be adjusted, and  bigger weddings  (up to about 150 guests) are designed with you. Jodi-Ann, our events coordinator, plans it with you. ", "k": "wedding price cost packages package", "l": [["Plan your wedding", "#events"]], "h": "<p>Our wedding packages, plus 10% GCT:</p><ul class=\"bm-ul\"><li><strong>Intimate Escape</strong>, up to 10 guests: from <strong>US$1,999</strong>. Bouquet and boutonniere, beach venue for up to 2 hours, officiant and coordinator, a one-tier cake and sparkling wine, a candlelight dinner for two.</li><li><strong>White Lux</strong>, up to 25 guests: from <strong>US$4,700</strong>. All-white roses, a floral arch, Chiavari chairs, cocktail tables, officiant and coordinator, sparkling wine, cake and hors d’oeuvres.</li><li><strong>FootePrints Signature Experience</strong>, up to 50 guests: from <strong>US$8,999</strong>. A rose bouquet, Louis chairs and floral pedestals, a reception tablescape, a beachfront or Gatsby’s venue for up to 4 hours, officiant and coordinator, cake and a sparkling wine toast, breakfast in bed and a room upgrade (based on availability).</li></ul><p>Packages are for the wedding itself; <strong>rooms are booked separately</strong>. Every package can be adjusted, and <strong>bigger weddings</strong> (up to about 150 guests) are designed with you. Jodi-Ann, our events coordinator, plans it with you.</p>", "n": []}, {"t": "events", "s": "Weddings", "q": "What do we need to marry in Jamaica?", "a": "There is <strong>no residency requirement or waiting period</strong>. You can marry 24 hours after you arrive, and the marriage licence is issued the same day.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Weddings", "q": "Can we see the hotel first?", "a": "<strong>Yes.</strong> We offer complimentary venue tours for couples, by appointment.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Weddings", "q": "Can our guests stay with us?", "a": "<strong>Yes</strong>, in the same place as the party: 32 rooms, around 64 guests, continental breakfast included.", "k": "", "l": [["See the rooms", "#stay"]], "n": []}, {"t": "events", "s": "Weddings", "q": "Can we change what’s in a package?", "a": "<strong>Yes.</strong> Every package can be adjusted. Reception décor and dinner can be added, and bigger weddings are designed with you.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Weddings", "q": "Who plans the day with us?", "a": "<strong>Jodi-Ann</strong>, our events coordinator, and a dedicated coordinator on the day.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Parties", "q": "How many guests can you host?", "a": " From  just the two of you  to a reception for  about 150 guests .  For your guests to stay with you, you can book  the whole hotel: all 32 rooms , around 64 guests. ", "k": "", "l": [], "n": [], "h": "<p>From <strong>just the two of you</strong> to a reception for <strong>about 150 guests</strong>.</p><p>For your guests to stay with you, you can book <strong>the whole hotel: all 32 rooms</strong>, around 64 guests.</p>"}, {"t": "events", "s": "Parties", "q": "Can we book the whole hotel?", "a": "<strong>Yes</strong>, depending on your dates: all 32 rooms, around 64 guests staying in the same place as the party.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Parties", "q": "Do you do the food and décor?", "a": "<strong>Yes.</strong> We plan the food and drink with you, from plated dinners to buffets, and take care of the table setting and décor.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Parties", "q": "How much does a party cost?", "a": "Every celebration is priced for your guest list and your menu. Send us a request and we’ll reply with options and prices.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Parties", "q": "Can guests who aren’t staying come?", "a": "<strong>Yes.</strong> Your guests are welcome whether they stay with us or not.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Private dinners", "q": "Where can we have a private dinner?", "a": "On the <strong>beach</strong>, or at one of <strong>two spots on the Skywalk</strong> facing the sunset.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Private dinners", "q": "Can you help with a proposal?", "a": "<strong>Yes.</strong> Tell us your plan when you send the request, and we’ll set the table and keep it a surprise.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Private dinners", "q": "Do we need to stay at the hotel?", "a": "<strong>No.</strong> Private dinners are open to everyone.", "k": "", "l": [], "n": []}, {"t": "events", "s": "Private dinners", "q": "How far ahead should we book?", "a": "As early as you can, especially for a special date. Tell us the date and we’ll confirm.", "k": "", "l": [], "n": []}, {"t": "retreats", "s": "", "q": "Can we bring a group, a retreat or our company?", "a": "Yes. Wellness retreats, workshops, team trips and family reunions are all welcome, and <strong>the whole hotel can be yours</strong>.\n\nFor meetings and conferences, your team has a <strong>professional event space</strong>: <strong>3,300 sq ft</strong>, air-conditioned, with flexible layouts, <strong>two 75-inch screens</strong>, a projector, Wi-Fi, hybrid set-up and on-site tech support.", "k": "", "l": [["Retreats and groups", "#retreats"]], "n": []}, {"t": "retreats", "s": "Corporate retreats", "q": "How many people can you host?", "a": " The whole hotel is  32 rooms, around 64 guests . Smaller groups are welcome too. ", "k": "", "l": [], "n": [], "h": "<p>The whole hotel is <strong>32 rooms, around 64 guests</strong>. Smaller groups are welcome too.</p>"}, {"t": "retreats", "s": "Corporate retreats", "q": "Can we have the whole hotel to ourselves?", "a": "  Yes , depending on your dates. Tell us when you’d like to come and we’ll check. ", "k": "", "l": [], "n": [], "h": "<p><strong>Yes</strong>, depending on your dates. Tell us when you’d like to come and we’ll check.</p>"}, {"t": "retreats", "s": "Corporate retreats", "q": "Do you have group rates?", "a": "  Yes.  Group rates are quoted for your dates and group size. Send us a request and we’ll reply with a rate. ", "k": "", "l": [], "n": [], "h": "<p><strong>Yes.</strong> Group rates are quoted for your dates and group size. Send us a request and we’ll reply with a rate.</p>"}, {"t": "retreats", "s": "Corporate retreats", "q": "What’s in the meeting room?", "a": "  3,300 sq ft , air-conditioned, with flexible layouts,  two 75-inch screens , a projector, Wi-Fi, a hybrid set-up and tech support on site. ", "k": "", "l": [], "n": [], "h": "<p><strong>3,300 sq ft</strong>, air-conditioned, with flexible layouts, <strong>two 75-inch screens</strong>, a projector, Wi-Fi, a hybrid set-up and tech support on site.</p>"}, {"t": "retreats", "s": "Corporate retreats", "q": "How far is the airport?", "a": " About  1 hour 30 minutes  from Sangster International Airport in Montego Bay. We can arrange transfers for your group. ", "k": "", "l": [], "n": [], "h": "<p>About <strong>1 hour 30 minutes</strong> from Sangster International Airport in Montego Bay. We can arrange transfers for your group.</p>"}, {"t": "retreats", "s": "Corporate retreats", "q": "How do we pay?", "a": " By  card . FootePrints is a  cashless  property. ", "k": "", "l": [], "n": [], "h": "<p>By <strong>card</strong>. FootePrints is a <strong>cashless</strong> property.</p>"}, {"t": "retreats", "s": "Partner retreats", "q": "Do you rent the space, or build the event with us?", "a": "  Both can work.  Some partners book rooms and spaces for their guests; others create the event together with us. Tell us what you have in mind. ", "k": "", "l": [], "n": [], "h": "<p><strong>Both can work.</strong> Some partners book rooms and spaces for their guests; others create the event together with us. Tell us what you have in mind.</p>"}, {"t": "retreats", "s": "Partner retreats", "q": "Can my guests stay at the hotel?", "a": "  Yes.  We have 32 rooms, around 64 guests, steps from the beach. ", "k": "", "l": [], "n": [], "h": "<p><strong>Yes.</strong> We have 32 rooms, around 64 guests, steps from the beach.</p>"}, {"t": "retreats", "s": "Partner retreats", "q": "How far ahead should we get in touch?", "a": "  As early as you can.  Bigger events need several months to plan, and dates book up. ", "k": "", "l": [], "n": [], "h": "<p><strong>As early as you can.</strong> Bigger events need several months to plan, and dates book up.</p>"}, {"t": "retreats", "s": "Partner retreats", "q": "Who reads my proposal?", "a": " Our team, together with the hotel’s management. If it’s a fit, we’ll set up a call. ", "k": "", "l": [], "n": [], "h": "<p>Our team, together with the hotel’s management. If it’s a fit, we’ll set up a call.</p>"}, {"t": "soundscape", "s": "", "q": "What is Soundscape?", "a": "A <strong>four-day beach club weekend</strong> at FootePrints on Seven Mile Beach in Negril, <strong>28 – 31 May 2027</strong>: DJ sets and live music by the water, wellness in the mornings, good food all day, and relaxed beach club evenings into the night. Not a nightclub.\n\nTickets aren’t on sale yet: <strong>join the early list</strong> to hear first.", "k": "", "l": [], "n": []}, {"t": "soundscape", "s": "", "q": "When is Soundscape?", "a": "<strong>28 – 31 May 2027</strong>, at FootePrints on Seven Mile Beach in Negril.", "k": "", "l": [], "n": ["Tickets aren’t on sale yet: <strong>join the early list</strong> to hear first, free and with no commitment."]}, {"t": "soundscape", "s": "", "q": "Are tickets on sale?", "a": "<strong>Not yet.</strong> Join the early list and we’ll tell you first when they open.", "k": "", "l": [], "n": []}, {"t": "soundscape", "s": "", "q": "What’s the difference between the Stay + Access Package and the Access Pass?", "a": "The <strong>Stay + Access Package</strong> is three nights at FootePrints for two, with daily breakfast and full Soundscape access for four days. The <strong>Access Pass</strong> is four days of Soundscape for guests staying anywhere in Negril.", "k": "", "l": [], "n": ["Tickets aren’t on sale yet: <strong>join the early list</strong> to hear first, free and with no commitment."]}, {"t": "soundscape", "s": "", "q": "How much will it cost?", "a": "Prices will be announced when tickets go on sale. <strong>Everyone on the early list hears first.</strong>", "k": "", "l": [], "n": []}, {"t": "soundscape", "s": "", "q": "Who’s playing?", "a": "We’ll share the line-up as soon as it’s confirmed. Join the early list to hear first.", "k": "", "l": [], "n": []}, {"t": "soundscape", "s": "", "q": "Is it a party?", "a": "It’s a <strong>beach club weekend</strong>: DJs and live music by the sea, good food, wellness in the mornings and relaxed evenings. Not a nightclub.", "k": "", "l": [], "n": ["Tickets aren’t on sale yet: <strong>join the early list</strong> to hear first, free and with no commitment."]}, {"t": "soundscape", "s": "", "q": "Does joining the list mean I’ve booked?", "a": "<strong>No.</strong> It’s free, with no commitment. We’ll simply tell you when tickets open so you can decide.", "k": "", "l": [], "n": ["Tickets aren’t on sale yet: <strong>join the early list</strong> to hear first, free and with no commitment."]}, {"t": "here", "s": "", "q": "Where is FootePrints?", "a": "On <strong>Norman Manley Boulevard, Seven Mile Beach, Negril</strong>, in Westmoreland, Jamaica. The hotel sits right on the beach.", "k": "address location map directions", "l": [["Open in Google Maps", "https://maps.google.com/?cid=14330021778143336711"]], "n": []}, {"t": "here", "s": "", "q": "How long is the drive from the airport?", "a": "From the <strong>Montego Bay airport</strong>, about <strong>1 hour 30 minutes</strong> without traffic. From Ocho Rios it’s about <strong>3 hours</strong>, and from Kingston about <strong>4 hours</strong>.\n\nWe can arrange an airport transfer: ask our reservations team.", "k": "", "l": [["Email reservations", "mailto:reservations@negrilfooteprints.com"]], "n": []}, {"t": "here", "s": "", "q": "Is there parking?", "a": "Yes. There is <strong>one car park on site</strong>, used by hotel guests and Day Pass visitors alike.", "k": "", "l": [], "n": []}, {"t": "here", "s": "", "q": "What are your opening hours?", "a": "<strong>Breakfast</strong> 7:30 – 11 AM and <strong>lunch</strong> 11 AM – 6 PM at Blushy’s. <strong>Dinner</strong> at Gatsby’s 6 – 10 PM, last seating at 9 PM. <strong>Happy hour</strong> at Blushy’s every day, 4 – 6 PM.\n\n<strong>Day Pass</strong> and <strong>Audrey’s Spa</strong>: daily, 9 AM – 5 PM. The <strong>front desk</strong> is open 7 AM – 11 PM. Hotel <strong>check-in from 3 PM</strong>, <strong>check-out by 12 PM</strong>.", "k": "spa hours breakfast lunch dinner daypass times when open", "l": [["Dining and menus", "#dining"], ["Day Pass", "#daypass"], ["Audrey’s Spa", "#spa"]], "n": []}, {"t": "here", "s": "", "q": "What’s on at the hotel?", "a": "A <strong>bonfire on the beach every Saturday at 7 PM</strong>, free for everyone: hotel guests and visitors. Happy hour at Blushy’s Bar &amp; Grill is every day from 4 to 6 PM, with 2-for-1 on selected drinks.\n\nNext big date: <strong>Soundscape, 28 – 31 May 2027</strong>.", "k": "", "l": [["Soundscape", "#soundscape"], ["Drinks menu", "#menu-drinks"]], "n": []}, {"t": "here", "s": "", "q": "How do I contact the hotel?", "a": "<strong>WhatsApp</strong> +1 855 822-3591 · <strong>Call</strong> +1 718 785-0558.\n\nCalling from Jamaica: 876 601-0028, 876 940-6707 or 876 940-6487 (<strong>phone calls only</strong>, no WhatsApp).\n\nBy email: <strong>reservations@negrilfooteprints.com</strong> for rooms; <strong>frontdesk@negrilfooteprints.com</strong> for dining, the spa, candlelight dinners and general questions; <strong>weddingandevents@negrilfooteprints.com</strong> for weddings and events; <strong>media@negrilfooteprints.com</strong> for brands, press and creators.", "k": "phone number email whatsapp call reach", "l": [["WhatsApp", "https://wa.me/18558223591"], ["Call", "tel:+17187850558"], ["Email the front desk", "mailto:frontdesk@negrilfooteprints.com"]], "n": []}, {"t": "here", "s": "", "q": "Do you take cash?", "a": "<strong>No.</strong> FootePrints is a <strong>cashless property</strong>, so please bring a card.", "k": "cash pay paying payment", "l": [], "n": []}, {"t": "work", "s": "", "q": "How can I work with FootePrints?", "a": " There are a few ways, depending on who you are:    Creators and models:  apply through one short form. We read every application, and if there’s a good fit we reach out by email or DM.   Brands, press and agencies:  email our media team at  media@negrilfooteprints.com .   Travel agents and tour operators:  for rates and group bookings, write to  reservations@negrilfooteprints.com .   Jobs at the hotel:  apply on our Work with us page in a few minutes, no CV needed yet. We contact applicants when a role opens that fits their experience.  ", "h": "<p>There are a few ways, depending on who you are:</p><ul class=\"bm-ul\"><li><strong>Creators and models:</strong> apply through one short form. We read every application, and if there’s a good fit we reach out by email or DM.</li><li><strong>Brands, press and agencies:</strong> email our media team at <strong>media@negrilfooteprints.com</strong>.</li><li><strong>Travel agents and tour operators:</strong> for rates and group bookings, write to <strong>reservations@negrilfooteprints.com</strong>.</li><li><strong>Jobs at the hotel:</strong> apply on our Work with us page in a few minutes, no CV needed yet. We contact applicants when a role opens that fits their experience.</li></ul>", "k": "work with you collaborate collaboration partner partnership apply join opportunities", "l": [["Apply as a creator or model", "https://tally.so/r/kdpAAd"], ["Email the media team", "mailto:media@negrilfooteprints.com"], ["Apply for a job", "#work"]], "n": []}, {"t": "work", "s": "Creators", "q": "Do I need a big following?", "a": "<strong>No.</strong> Follower count isn’t how we choose: we look at your content and how your audience responds to it.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Creators", "q": "I don’t have hotel, restaurant or spa content yet. Should I still apply?", "a": "We’d suggest creating some first, then applying. <strong>Hospitality content is what we look at most</strong>, and without it we’re unlikely to be able to work together.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Creators", "q": "How do you use my content?", "a": "We repost it on our channels <strong>with credit</strong>. Any paid advertising is agreed separately, in writing.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Models", "q": "Do you provide outfits for shoots?", "a": "<strong>No.</strong> Models bring their own outfits, so please apply only if you have pieces that suit a relaxed, refined beachfront hotel.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Models", "q": "How long is a shoot?", "a": "Usually <strong>a full day, about 8 hours with breaks</strong>, during a two-night stay in Negril.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Models", "q": "Do I need to live in Jamaica?", "a": "<strong>Yes.</strong> Model applications are for people based in Jamaica who can come to Negril for a two-night stay if selected.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Creators & models", "q": "Can I apply as both a creator and a model?", "a": "<strong>Yes.</strong> Choose the path closest to you in the first question. At the end of the form you can ask us to consider you for both.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Creators & models", "q": "Are collaborations paid?", "a": "It depends on the collaboration. The form asks how you’d like to work: complimentary, paid, or open to discussing. <strong>Everything is agreed in writing before you arrive.</strong>", "k": "", "l": [], "n": []}, {"t": "work", "s": "Creators & models", "q": "Do you work with outside photographers or videographers?", "a": "<strong>No.</strong> We produce our own photography and video, so we are not taking on outside photographers or videographers.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Creators & models", "q": "When will I hear back?", "a": "We read every application personally. <strong>If there’s a good fit, we’ll reach out by email or DM.</strong>", "k": "", "l": [], "n": []}, {"t": "work", "s": "Brands & press", "q": "I’m a travel agent or tour operator. Who do I contact?", "a": "Our reservations team: <strong>reservations@negrilfooteprints.com</strong>, for rates, group bookings and availability.", "k": "", "l": [["Email reservations", "mailto:reservations@negrilfooteprints.com"]], "n": []}, {"t": "work", "s": "Brands & press", "q": "Who reads my email?", "a": "Our media team, which looks after the FootePrints brand, social media and partnerships.", "k": "", "l": [], "n": []}, {"t": "work", "s": "Careers", "q": "Do I need a CV to apply?", "a": "<strong>Not at this step.</strong> If you have a CV or LinkedIn online, you can add the link. If a role fits, we’ll ask for your full CV.", "k": "job jobs career", "l": [], "n": []}, {"t": "work", "s": "Careers", "q": "What kinds of roles are there?", "a": "Roles across the hotel: front desk and reservations, housekeeping, the kitchen, the restaurant and bar, the spa, and maintenance and grounds. Choose up to three areas in the form.", "k": "job jobs vacancy vacancies hiring career careers work", "l": [], "n": []}, {"t": "work", "s": "Careers", "q": "Where is the hotel?", "a": "On Norman Manley Boulevard, Seven Mile Beach, Negril, Westmoreland.", "k": "", "l": [], "n": []}], "topics": [{"k": "stay", "n": "Rooms & stays", "h": "#stay", "c": 15}, {"k": "daypass", "n": "Day Pass", "h": "#daypass", "c": 12}, {"k": "dining", "n": "Dining & menus", "h": "#dining", "c": 13}, {"k": "spa", "n": "Audrey’s Spa", "h": "#spa", "c": 8}, {"k": "events", "n": "Weddings & celebrations", "h": "#events", "c": 16}, {"k": "retreats", "n": "Retreats & groups", "h": "#retreats", "c": 11}, {"k": "soundscape", "n": "Soundscape 2027", "h": "#soundscape", "c": 8}, {"k": "here", "n": "Getting here & contacts", "h": "", "c": 7}, {"k": "work", "n": "Work with us", "h": "#work", "c": 16}], "start": [0, 1, 15, 29, 2, 47], "routes": [{"need": [["collab", "collabs", "collaboration", "collaborations", "collaborate", "creator", "creators", "influencer", "influencers", "ugc", "blogger", "bloggers", "vlogger", "model", "models", "modelling", "modeling", "shoot"]], "not": ["photographer", "photographers", "videographer"], "a": "<strong>Yes, we work with creators and models.</strong> Everyone applies through one short form: choose “creator” or “model” in the first question and tell us about your work.\n\nWe read every application personally. <strong>If there’s a good fit, we’ll reach out by email or DM.</strong>", "l": [["Apply as a creator or model", "https://tally.so/r/kdpAAd"], ["Work with us", "#work"]]}, {"need": [["press", "journalist", "journalists", "magazine", "brand", "brands", "sponsor", "sponsorship", "pr", "feature", "interview"]], "a": "For <strong>brand partnerships and press</strong>, please email our media team at <strong>media@negrilfooteprints.com</strong>. They look after the FootePrints brand, social media and partnerships.", "l": [["Email the media team", "mailto:media@negrilfooteprints.com"], ["Work with us", "#work"]]}, {"need": [["job", "jobs", "vacancy", "vacancies", "hiring", "career", "careers", "employment", "position", "positions", "cv", "resume"]], "a": "We’d be glad to hear from you. <strong>Apply on our Work with us page</strong>: tell us about yourself and choose up to three areas of the hotel.\n\nWe contact applicants <strong>when a role opens that fits their experience</strong>, and we keep your details for future roles.", "l": [["Apply for a job", "#work"]]}, {"need": [["book", "booking", "reserve", "buy", "ticket", "tickets", "get"], ["daypass"]], "a": "You can <strong>book your Day Pass online</strong>: pick your date, even for today. It’s <strong>$30 per adult</strong>, <strong>$20 for ages 4–12</strong> and <strong>free for ages 0–3</strong>, daily from 9 AM to 5 PM.\n\nSpaces are limited, so it’s best to book ahead.", "l": [["Book a Day Pass", "https://www.tickettailor.com/events/negrilfooteprintshotel/2452834"], ["Day Pass details", "#daypass"]]}, {"need": [["book", "booking", "reserve", "reservation", "table"], ["dinner", "gatsby", "gatsbys", "table", "restaurant"]], "a": "<strong>Book a table at Gatsby’s online</strong>: dinner is served daily from <strong>6 to 10 PM</strong>, with the last guests seated at 9 PM. Walk-ins are welcome, but we recommend booking dinner.", "l": [["Reserve at Gatsby’s", "https://eatapp.co/reserve/gatsby-s-restaurant-at-negril-footeprints-hotel-fa5d27"], ["See the dinner menu", "#menu-dinner"]]}, {"need": [["book", "booking", "reserve", "appointment", "schedule"], ["spa", "massage", "massages", "treatment", "treatments", "facial"]], "a": "Choose your treatment on the <strong>Audrey’s Spa</strong> page and tap <strong>Book a treatment</strong> to send a request. Our front desk <strong>replies to confirm your time</strong>, or suggests the closest one that’s free.\n\nThe spa is open daily, <strong>9 AM – 5 PM</strong>.", "l": [["Audrey’s Spa and treatments", "#spa"]]}, {"need": [["book", "booking", "reserve", "reservation", "availability", "available", "vacancy"], ["room", "rooms", "stay", "night", "nights", "suite", "suites", "hotel"]], "a": "Rooms start at <strong><span class=\"rate\">$259</span> per night for two</strong>, per room, with continental breakfast. You can <strong>book online</strong>, or choose a room on our Stay page and <strong>send a request</strong>: you’ll see the full price for your dates first, and our team replies within 24–48 hours.", "l": [["See the rooms", "#stay"], ["Book online", "https://negrilfooteprints.com/search-results/"]]}, {"need": [["book", "booking", "plan", "planning", "enquire", "enquiry", "inquiry", "inquire", "quote", "organise", "organize", "host"], ["wedding", "weddings", "event", "events", "party", "birthday", "celebration", "proposal", "shower", "anniversary"]], "a": "We’d love to help. On our <strong>Celebrations</strong> page, choose your occasion and send a request with your date and number of guests: our events team will get back to you.\n\nYou can also email <strong>weddingandevents@negrilfooteprints.com</strong>.", "l": [["Plan a celebration", "#events"], ["Email the events team", "mailto:weddingandevents@negrilfooteprints.com"]]}, {"need": [["menu", "menus"]], "not": ["child", "children", "kids", "kid", "order"], "a": "Here are our menus. <strong>Breakfast</strong> (7:30 – 11 AM) and <strong>lunch</strong> (11 AM – 6 PM) are at Blushy’s on the beach; <strong>dinner</strong> (6 – 10 PM) is at Gatsby’s.", "l": [["Breakfast", "#menu-breakfast"], ["Lunch", "#menu-lunch"], ["Dinner", "#menu-dinner"], ["Drinks", "#menu-drinks"]]}]};